  render: () => <Box sx={{
    p: 4
  }}>
      <Stack spacing={4}>
        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            User List
          </MuiTypography>
          <Stack spacing={2}>
            {[{
            name: 'John Doe',
            initials: 'JD',
            img: 'https://i.pravatar.cc/150?img=10'
          }, {
            name: 'Jane Smith',
            initials: 'JS',
            img: 'https://i.pravatar.cc/150?img=11'
          }, {
            name: 'Bob Johnson',
            initials: 'BJ',
            img: 'https://i.pravatar.cc/150?img=12'
          }].map((user, index) => <Box key={index} sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 2
          }}>
                <Avatar src={user.img} alt={user.name}>
                  {user.initials}
                </Avatar>
                <MuiTypography>{user.name}</MuiTypography>
              </Box>)}
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Comment Thread
          </MuiTypography>
          <Stack spacing={2}>
            {[{
            initials: 'AB',
            comment: 'Great work on this!'
          }, {
            initials: 'CD',
            comment: 'Thanks for the feedback!'
          }, {
            initials: 'EF',
            comment: 'Looking forward to the next iteration.'
          }].map((item, index) => <Box key={index} sx={{
            display: 'flex',
            gap: 2
          }}>
                <Avatar size={32}>{item.initials}</Avatar>
                <Box sx={{
              flex: 1
            }}>
                  <MuiTypography variant="body2">{item.comment}</MuiTypography>
                </Box>
              </Box>)}
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Team Members (Small)
          </MuiTypography>
          <Stack direction="row" spacing={1}>
            {['AM', 'BP', 'CQ', 'DR', 'ES'].map((initials, index) => <Avatar key={index} size={24}>
                {initials}
              </Avatar>)}
          </Stack>
        </Box>
      </Stack>
    </Box>,
  parameters: {
    layout: 'fullscreen'
  }
